        "title": "精准浆腌下料",
        "instruction": "猪肝加米酒、生抽、姜丝、白胡椒粉、淀粉抓拌薄浆，猪肉糜加盐姜末沿顺时针搅打上劲捏成3颗小肉丸备用。",
