        "title": "大火生滚粉肠45秒",
        "instruction": "大火沸腾状态下，投入大量细姜丝与腌好的粉肠段，用筷子迅速推散，粉肠两端受热收缩卷曲，煮约45秒关火。",
        "timerSeconds": 60,
        "chefTip": "粉肠生滚时间控制在45秒内，关火借余热烫熟，外皮爽脆内里粉润，久煮则韧如皮筋。"
