        "stepIndex": 4,
        "title": "下糯米红枣桂圆慢煲成沙",
        "instruction": "下入淘洗好的糯米、绿豆、红枣和桂圆干，大火煮沸后转中小火加盖慢熬30分钟，豆粒爆开发沙，米汁浓稠如锦缎。",
