    "proTips": "红心蜜地瓜大块冷水下锅慢熬，让地瓜内部淀粉充分水解成麦芽糖，地瓜外融内糯，微盐引出极致甘甜，台湾传唱百年的古早味稀饭。",
    "nutritionHighlights": "地瓜富含膳食纤维、胡萝卜素、维生素A与钾，通便排毒、平稳血压，温和滋养肠胃。"
